mapper.select:
SELECT id, download_path, icon_url, md5, app_name, android_package_name, version_num, adapt_phone_system, online, use_able, version_description, update_time FROM system_base.t_app_version_msg t WHERE t.online = true AND t.use_able = true AND t.adapt_phone_system = #{adaptPhoneSystem}
AND t.version_num > #{versionNum}
ORDER BY version_num DESC LIMIT 1
